PRAGMA foreign_keys=ON;
-- Final chapter method QAs, original cases, cross-domain same-event witnesses, OCR and errors.
CREATE TABLE IF NOT EXISTS kaiwu_final_subsections(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),section_number INTEGER NOT NULL,source_start INTEGER NOT NULL,source_end INTEGER NOT NULL,source_heading TEXT NOT NULL,source_sha256 TEXT NOT NULL,PRIMARY KEY(chapter_key,section_number));
CREATE TABLE IF NOT EXISTS kaiwu_final_qa(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),qa_key TEXT NOT NULL,subsection_number INTEGER NOT NULL,question_line INTEGER NOT NULL,answer_start INTEGER NOT NULL,answer_end INTEGER NOT NULL,question_original TEXT NOT NULL,answer_original TEXT NOT NULL,question_sha256 TEXT NOT NULL,answer_sha256 TEXT NOT NULL,conditions_json TEXT NOT NULL CHECK(json_valid(conditions_json)),review_status TEXT NOT NULL DEFAULT 'draft',PRIMARY KEY(chapter_key,qa_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_event_witnesses(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),witness_key TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES cases(case_id),subsection_number INTEGER NOT NULL,start_line INTEGER NOT NULL,end_line INTEGER NOT NULL,relation TEXT NOT NULL,source_original TEXT NOT NULL,source_sha256 TEXT NOT NULL,meta_json TEXT NOT NULL CHECK(json_valid(meta_json)),PRIMARY KEY(chapter_key,witness_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_raw_casts(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),cast_key TEXT NOT NULL,source_start INTEGER NOT NULL,source_end INTEGER NOT NULL,source_original TEXT NOT NULL,source_sha256 TEXT NOT NULL,original_plate_positions_certified INTEGER NOT NULL DEFAULT 0 CHECK(original_plate_positions_certified=0),PRIMARY KEY(chapter_key,cast_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_raw_cast_lines(chapter_key TEXT NOT NULL,cast_key TEXT NOT NULL,source_line INTEGER NOT NULL,source_original TEXT NOT NULL,source_sha256 TEXT NOT NULL,PRIMARY KEY(chapter_key,cast_key,source_line),FOREIGN KEY(chapter_key,cast_key) REFERENCES kaiwu_final_raw_casts(chapter_key,cast_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_cast_case_links(chapter_key TEXT NOT NULL,cast_key TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES cases(case_id),cast_context TEXT NOT NULL,PRIMARY KEY(chapter_key,cast_key,case_id),FOREIGN KEY(chapter_key,cast_key) REFERENCES kaiwu_final_raw_casts(chapter_key,cast_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_source_phases(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),phase_key TEXT NOT NULL,phase_kind TEXT NOT NULL,first_line INTEGER NOT NULL,last_line INTEGER NOT NULL,source_original TEXT NOT NULL,source_sha256 TEXT NOT NULL,available_at_first_forecast INTEGER NOT NULL CHECK(available_at_first_forecast IN(0,1)),meta_json TEXT NOT NULL CHECK(json_valid(meta_json)),PRIMARY KEY(chapter_key,case_id,phase_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_reasoning_units(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),unit_index INTEGER NOT NULL,source_line INTEGER NOT NULL,reasoner TEXT NOT NULL,reasoning_phase TEXT NOT NULL,original_text TEXT NOT NULL,source_sha256 TEXT NOT NULL,evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),positive_training_eligible INTEGER NOT NULL DEFAULT 0 CHECK(positive_training_eligible=0),PRIMARY KEY(chapter_key,case_id,unit_index));
CREATE TABLE IF NOT EXISTS kaiwu_final_error_audit(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),error_key TEXT NOT NULL,error_axis TEXT NOT NULL,prediction_line INTEGER NOT NULL,correction_line INTEGER NOT NULL,original_prediction TEXT NOT NULL,original_later_correction TEXT NOT NULL,original_intact INTEGER NOT NULL DEFAULT 1 CHECK(original_intact=1),PRIMARY KEY(chapter_key,case_id,error_key));
CREATE TABLE IF NOT EXISTS kaiwu_final_method_candidates(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),method_key TEXT NOT NULL,source_line INTEGER NOT NULL,source_original TEXT NOT NULL,method_domain TEXT NOT NULL,preconditions_json TEXT NOT NULL CHECK(json_valid(preconditions_json)),limitations_json TEXT NOT NULL CHECK(json_valid(limitations_json)),review_status TEXT NOT NULL DEFAULT 'draft' CHECK(review_status='draft'),positive_training_eligible INTEGER NOT NULL DEFAULT 0 CHECK(positive_training_eligible=0),PRIMARY KEY(chapter_key,method_key));
